mapper.select:
/* 제재 Rule 등록 (7050) */
/* AdminSanctionMapper.selectInfoRule1 */
SELECT
	AI_INPT_RULE_DSCD, AI_INPT_SNRL1_ID, AI_INPT_SNRL1_NM, INPT_SANCTION_NO, AI_INPT_LIST_ID
FROM CSPD105TI
WHERE AI_INPT_SNRL1_ID = #{aiInptSnrl1Id}

/* 제재 Rule 등록 (7050) */ /* AdminSanctionMapper.selectListRule2 */ SELECT AI_INPT_RULE_DSCD, AI_INPT_SNRL2_ID, AI_INPT_SNRL2_NM, INPT_SANCTION1_NO, AI_INPT_LIST1_ID, INPT_SANCTION2_NO, AI_INPT_LIST2_ID, INPT_SANCTION3_NO, AI_INPT_LIST3_ID, INPT_SANCTION4_NO, AI_INPT_LIST4_ID FROM CSPD106TI WHERE 1=1
AND AI_INPT_RULE_DSCD = #{schGbn}
ORDER BY AI_INPT_SNRL2_NM
ORDER BY AI_INPT_SNRL2_NM DESC
ORDER BY AI_INPT_SNRL2_NM

/* 제재 Rule 등록 (7050) */
/* AdminSanctionMapper.selectInfoRule2 */
SELECT
	AI_INPT_RULE_DSCD, AI_INPT_SNRL2_ID, AI_INPT_SNRL2_NM,
	INPT_SANCTION1_NO, AI_INPT_LIST1_ID, INPT_SANCTION2_NO, AI_INPT_LIST2_ID, 
	INPT_SANCTION3_NO, AI_INPT_LIST3ID, INPT_SANCTION4_NO, AI_INPT_LIST4ID
FROM CSPD106TI
WHERE AI_INPT_SNRL2_ID = #{aiInptSnrl2Id}

/* 제재 Rule 등록 (7050) */
/* AdminSanctionMapper.selectListRule3 */
SELECT
	AI_INPT_SNRL3_ID, AI_INPT_SNRL3_NM, AI_INPT_RSPT_SQL_TXT
FROM CSPD113TI
ORDER BY AI_INPT_SNRL3_ID DESC

/* 제재 Rule 등록 (7050) */
/* AdminSanctionMapper.selectInfoRule3 */
SELECT
	AI_INPT_SNRL3_ID, AI_INPT_SNRL3_NM, AI_INPT_RSPT_SQL_TXT
FROM CSPD113TI
WHERE AI_INPT_SNRL3_ID = #{aiInptSnrl3Id}

/* 제재 Rule 등록 (7050) */
/* AdminSanctionMapper.RequestTable */
SELECT
	AI_INPT_RULE_DSCD, AI_INPT_WORD_ACRD_RT, AI_INPT_SNRL2_USG_YN, AI_INPT_SNRL3_USG_YN
FROM CSPD116TI
WHERE 1=1

	AND AI_INPT_RULE_DSCD = #{schGbn}

SELECT AI_INPT_SNRL1_ID 
FROM CSPD105TI A
WHERE 1=1
AND AI_INPT_RULE_DSCD = #{aiInptRuleDscd} 
AND AI_INPT_LIST_ID = #{aiInptListId}

mapper.insert:
/* 제재 Rule 등록 (7050) */ /* AdminSanctionMapper.insertRule2 */
SELECT SUBSTR('00'||(TO_NUMBER(NVL(MAX(AI_INPT_SNRL2_ID),0)) + 1),-2) FROM CSPD106TI
MERGE INTO CSPD106TI A USING DUAL ON (A.AI_INPT_SNRL2_ID = #{aiInptSnrl2Id}) WHEN MATCHED THEN UPDATE SET A.AI_INPT_SNRL2_NM = #{aiInptSnrl2Nm}, A.INPT_SANCTION1_NO = #{inptSanction1No}, A.AI_INPT_LIST1_ID = #{aiInptList1Id}, A.INPT_SANCTION2_NO = #{inptSanction2No}, A.AI_INPT_LIST2_ID = #{aiInptList2Id}, A.INPT_SANCTION3_NO = #{inptSanction3No}, A.AI_INPT_LIST3_ID = #{aiInptList3Id}, A.INPT_SANCTION4_NO = #{inptSanction4No}, A.AI_INPT_LIST4_ID = #{aiInptList4Id}, A.TRN_LOG_SRNO = #{trnLogSrno}, A.LST_DB_CHG_ID = #{lstDbChgId}, A.LST_DB_CHG_DTM = WHEN NOT MATCHED THEN INSERT (A.AI_INPT_SNRL2_ID, A.AI_INPT_RULE_DSCD, A.AI_INPT_SNRL2_NM, A.INPT_SANCTION1_NO, A.AI_INPT_LIST1_ID, A.INPT_SANCTION2_NO, A.AI_INPT_LIST2_ID, A.INPT_SANCTION3_NO, A.AI_INPT_LIST3_ID, A.INPT_SANCTION4_NO, A.AI_INPT_LIST4_ID, A.TRN_LOG_SRNO, A.LST_DB_CHG_ID, A.LST_DB_CHG_DTM) VALUES (#{numNew}, #{aiInptRuleDscd}, #{aiInptSnrl2Nm}, #{inptSanction1No}, #{aiInptList1Id}, #{inptSanction2No}, #{aiInptList2Id}, #{inptSanction3No}, #{aiInptList3Id}, #{inptSanction4No}, #{aiInptList4Id}, #{trnLogSrno}, #{lstDbChgId}, )

mapper.delete:
/* 제재 Rule 등록 (7050) */
/* AdminSanctionMapper.deleteRule1 */
delete from CSPD105TI
where AI_INPT_SNRL1_ID = #{aiInptSnrl1Id}

/* 제재 Rule 등록 (7050) */
/* AdminSanctionMapper.deleteRule2 */
delete from CSPD106TI
where AI_INPT_SNRL2_ID = #{aiInptSnrl2Id}

/* 제재 Rule 등록 (7050) */
/* AdminSanctionMapper.deleteRule3 */
DELETE FROM CSPD113TI
WHERE AI_INPT_SNRL3_ID = #{aiInptSnrl3Id}
